// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _run(address jojoTeamAddr, string memory description) internal {
        vm.assume(jojoTeamAddr != address(this));
        jojoTeamAddr = c.jojoTeam();
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == true);
    }

    function testFuzz_run(address jojoTeamAddr, string memory description) public {
        _run(jojoTeamAddr, description);
    }

    receive() external payable { }
}
